package io.lumine.mythic.lib.player.inventory; import io.lumine.mythic.lib.api.player.EquipmentSlot; import io.lumine.mythic.lib.player.modifier.*; import java.util.*; public abstract class EquippedItem implements ModifierSupplier { protected final EquipmentSlot equipmentSlot; protected final int slotIndex,watcherId; protected final List<PlayerModifier> modifierCache=new ArrayList<>(); public EquippedItem(EquipmentSlot s){this(s,0,0);} public EquippedItem(int i){this(EquipmentSlot.INVENTORY,i,0);} public EquippedItem(int i,int w){this(EquipmentSlot.ACCESSORY,i,w);} public EquippedItem(EquipmentSlot s,int i,int w){equipmentSlot=s;slotIndex=i;watcherId=w;} public EquipmentSlot getEquipmentSlot(){return equipmentSlot;} public int getSlotIndex(){return slotIndex;} public int getWatcherId(){return watcherId;} public List<PlayerModifier> getModifierCache(){return modifierCache;} @Override public boolean equals(Object o){return this==o||o!=null&&getClass()==o.getClass()&&slotIndex==((EquippedItem)o).slotIndex&&watcherId==((EquippedItem)o).watcherId&&equipmentSlot==((EquippedItem)o).equipmentSlot;} @Override public int hashCode(){return Objects.hash(equipmentSlot,slotIndex,watcherId);} }
